import { z } from 'zod';

/** Opaque identifier used for every entity. Generated by the server. */
export const Id = z.string().min(1);
export type Id = z.infer<typeof Id>;

/** ISO-8601 timestamp with offset, always produced by the server. */
export const Timestamp = z.iso.datetime({ offset: true });
export type Timestamp = z.infer<typeof Timestamp>;

/**
 * Free-form bag for speculative or runtime-specific fields (IMPLEMENTATION_PLAN corner case 20):
 * anything not yet worth a schema column goes here, never in the schema itself.
 */
export const Meta = z.record(z.string(), z.unknown());
export type Meta = z.infer<typeof Meta>;
